import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as a,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"RLHF（桥接）","description":"基于人类反馈的强化学习的工程决策桥：模型行为与对齐从哪来，为什么应用工程师只需要理解它而不实施它。","frontmatter":{"title":"RLHF（桥接）","description":"基于人类反馈的强化学习的工程决策桥：模型行为与对齐从哪来，为什么应用工程师只需要理解它而不实施它。","domain":"tech","tags":["tech","training","bridge","rlhf"],"navOrder":142,"topicId":"model-lifecycle-rlhf","layer":"1","status":"bridge","nodeType":"boundary","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/"}],"lastVerified":"2026-09-01","listed":true},"headers":[],"relativePath":"zh/tech/01-model-lifecycle/post-training/rlhf.md","filePath":"zh/tech/01-model-lifecycle/post-training/rlhf.md","lastUpdated":1791169449000}'),l={name:"zh/tech/01-model-lifecycle/post-training/rlhf.md"};function n(i,t,h,d,s,c){return a(),e("div",null,[...t[0]||(t[0]=[o('<blockquote><p><strong>所在组</strong>：模型生命周期（桥接） ｜ <strong>上一组出口</strong>：理解推理基础与接口契约 ｜ <strong>本页出口</strong>：知道何时该动权重而不是改 Prompt 或上检索</p></blockquote><h1 id="rlhf-桥接" tabindex="-1">RLHF（桥接） <a class="header-anchor" href="#rlhf-桥接" aria-label="Permalink to &quot;RLHF（桥接）&quot;">​</a></h1><blockquote><p><strong>桥接页</strong>：本页只回答「RLHF 如何影响你的应用工程决策」。奖励建模、PPO/DPO 的训练机制推导在 <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>（RLHF/DPO 对应章节）。</p></blockquote><h2 id="解决什么问题" tabindex="-1">解决什么问题 <a class="header-anchor" href="#解决什么问题" aria-label="Permalink to &quot;解决什么问题&quot;">​</a></h2><p><strong>基于人类反馈的强化学习（Reinforcement Learning from Human Feedback, RLHF）</strong>：让人类对模型的多个输出排序，训练一个奖励模型来预测这些偏好，再用强化学习优化模型去最大化奖励分。它改变的不是模型「知道什么」（那是 SFT 和预训练的事），而是模型「怎么表现」——有用、诚实、无害的对齐行为主要来自这一步。</p><p>三步流程：</p><ol><li><strong>SFT</strong>：在人类演示上训练出基础能力。</li><li><strong>奖励建模</strong>：人类排序 → 训练奖励模型预测偏好。</li><li><strong>强化学习</strong>：优化模型输出以最大化奖励（PPO，或 Direct Preference Optimization 等 Direct 对齐变体）。</li></ol><h2 id="为什么应用工程师只理解、不实施" tabindex="-1">为什么应用工程师只理解、不实施 <a class="header-anchor" href="#为什么应用工程师只理解、不实施" aria-label="Permalink to &quot;为什么应用工程师只理解、不实施&quot;">​</a></h2><p>RLHF 需要：大规模人类反馈数据、专职研究团队、可观的训练算力。这是模型厂商（OpenAI、Anthropic、Google、Meta 等）在生产你通过 API 消费的模型时所做的工作。你的工程决策里<strong>不会出现「自己跑 RLHF」这个选项</strong>——如果你的需求是改行为，先检查主线工具箱：</p><ul><li>想要固定语气/格式 → <a href="./../../03-context/prompt.html">提示词工程</a> + few-shot 示例。</li><li>想要领域知识 → <a href="./../../04-grounding/rag.html">RAG</a>。</li><li>想要拒绝某类请求 → 输入校验 + 输出过滤（应用安全，见 <a href="./../../08-production/security.html">安全</a>）。</li></ul><h2 id="理解-rlhf-能解释的模型行为" tabindex="-1">理解 RLHF 能解释的模型行为 <a class="header-anchor" href="#理解-rlhf-能解释的模型行为" aria-label="Permalink to &quot;理解 RLHF 能解释的模型行为&quot;">​</a></h2><p>这是本页对你的真实价值——三个常见的「模型为什么这样」：</p><ol><li><strong>过度拒绝</strong>：对齐训练会让模型把边界放大，拒绝一些良性请求。产品侧应对：允许用户澄清重试，而不是接受拒绝为终态。</li><li><strong>冗长与对冲</strong>：模型爱说「作为一门 AI 语言模型…」、答案先铺垫一大段。产品侧应对：prompt 里约束输出形态，配合<a href="./../../02-inference-interface/structured-output.html">结构化输出</a>。</li><li><strong>模型「个性」</strong>：不同厂商模型的风格差异主要来自对齐阶段的偏好数据选择。选型时把「个性是否匹配产品语气」当评估项，见<a href="./../../08-production/evaluation.html">评估（桥接）</a>。</li></ol><h2 id="决策影响表" tabindex="-1">决策影响表 <a class="header-anchor" href="#决策影响表" aria-label="Permalink to &quot;决策影响表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>说明</th></tr></thead><tbody><tr><td><strong>数据量要求</strong></td><td>大规模人类偏好排序数据（厂商级投入，应用团队不具备）</td></tr><tr><td><strong>成本结构</strong></td><td>研究级：反馈采集 + 多轮训练 + 评估（本仓不引用具体数字）</td></tr><tr><td><strong>生效延迟</strong></td><td>模型版本级——你只能通过换模型/换版本「使用」新的对齐结果</td></tr><tr><td><strong>维护负担</strong></td><td>厂商承担；你的维护点是模型版本升级后的行为回归测试</td></tr></tbody></table><h2 id="sft-与-rlhf-的分工" tabindex="-1">SFT 与 RLHF 的分工 <a class="header-anchor" href="#sft-与-rlhf-的分工" aria-label="Permalink to &quot;SFT 与 RLHF 的分工&quot;">​</a></h2><p>把两页桥接放进同一张表，避免「都是训练」的混淆：</p><table tabindex="0"><thead><tr><th>问题</th><th>归属</th><th>改变的东西</th><th>你的参与方式</th></tr></thead><tbody><tr><td>模型不会我的领域/格式</td><td><a href="./sft.html">SFT</a></td><td>知识与技能（权重）</td><td>有数据与预算时可立项</td></tr><tr><td>模型的行为方式不对（语气、拒绝、冗长）</td><td>RLHF / 对齐</td><td>行为偏好（权重）</td><td>不立项——通过选型与 prompt 适配</td></tr><tr><td>模型缺实时/私有事实</td><td><a href="./../../04-grounding/rag.html">RAG</a></td><td>上下文（权重不变）</td><td>主线日常工作</td></tr></tbody></table><p>几乎所有旗舰聊天模型都经过 RLHF 或同类对齐（RLAIF / Constitutional AI 等）；差别主要体现为各厂商模型的「个性」与安全边界，这是选型评估的一部分。</p><h2 id="深层推导与实现" tabindex="-1">深层推导与实现 <a class="header-anchor" href="#深层推导与实现" aria-label="Permalink to &quot;深层推导与实现&quot;">​</a></h2><ul><li>奖励模型、PPO、DPO 的推导与对比 → <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a> 的 RLHF/DPO 章节。</li><li>延伸阅读（原始论文）：<a href="https://arxiv.org/abs/2203.02155" target="_blank" rel="noreferrer">InstructGPT</a>、<a href="https://arxiv.org/abs/2212.08073" target="_blank" rel="noreferrer">Constitutional AI</a>、<a href="https://openai.com/research/learning-from-human-preferences" target="_blank" rel="noreferrer">Deep RL from Human Preferences</a>。</li></ul>',21)])])}const b=r(l,[["render",n]]);export{u as __pageData,b as default};
